from scripts.goldset_validate import NUM

def sig_count(bare):
    return len(decimal.Decimal(bare).as_tuple().digits)
chars = ['0','1','2','9','.', '-', ',','%']
bad = []
accepted = 0
for length in range(1,9):
    for tup in itertools.product(chars, repeat=length):
        raw = ''.join(tup)
        # Simulate non-cell bare transformation relevant to NUM path.
        bare = raw.lstrip('$').replace(',', '').rstrip('%')
        if NUM.match(bare):
            accepted += 1
            try:
                digits = sig_count(bare)
            except Exception:
                continue
            if len(bare) < digits:
                bad.append((raw,bare,len(bare),digits))
                break
    if bad:
        break
print(f"accepted={accepted} bad={bad[:3]}")
